2.1 Entropy weight method
[m,n] = size(data);
a1 = zeros(m,n);
for i = 1:n
      a1(:,i) = (data(:,i)-min(data(:,i)))/(max(data(:,i))-min(data(:,i)));
end
ex=sum(a1);
a2=zeros(m,n);
for i=1:m
      for j=1:n
      a2(i,j)=a1(i,j)/ex(j);
      end
end
a3=a2.*log(a2);
a4=a3;
a4(find(isnan(a4)==1)) = 0;
ex=sum(a4);
ex1=-1/log(m)*ex;
weightAHP=(1-ex1)/(n-sum(ex1));

